{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 외장형 동물등록 장치 분실 재등록 시 등록수수료 감면 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제28조제4호에 따르면 무선식별장치가 훼손 또는 분실되어 재등록하는 경우 등록수수료를 50퍼센트 감면할 수 있습니다. 외장형 장치 분실로 인한 재등록도 이 감면 대상에 해당합니다. 다만 감면은 구청장의 재량으로 '할 수 있다'는 규정입니다.",
          "b_ids": "동물보호:제28조제4호, 동물보호:제28조"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 동물보호 조례상 재등록 시 등록대행 수수료도 함께 감면되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제28조 단서에 따르면 등록대행 수수료는 감면대상에서 제외됩니다. 따라서 무선식별장치 분실로 재등록 시 등록수수료가 50퍼센트 감면되더라도, 등록대행업체에 내는 수수료는 감면되지 않습니다.",
          "b_ids": "동물보호:제28조단서, 동물보호:제28조제4호"
        }
      ],
